public enum MessageStatus { Sent, Delivered, Read }

public class Message
{
    public Guid Id { get; } = Guid.NewGuid();
    public Guid ConversationId { get; }
    public Guid SenderId { get; }
    public string Content { get; set; }
    public DateTime SentAt { get; } = DateTime.UtcNow;
    public MessageStatus Status { get; private set; } = MessageStatus.Sent;
}

public abstract class Conversation
{
    public Guid Id { get; } = Guid.NewGuid();
    public List<Message> Messages { get; } = new();
    public abstract bool HasAccess(Guid userId);
}

public class DirectConversation : Conversation
{
    public Guid UserA { get; }
    public Guid UserB { get; }

    public override bool HasAccess(Guid userId) => userId == UserA || userId == UserB;
}

public class GroupConversation : Conversation
{
    public string Name { get; set; }
    public Guid AdminId { get; set; }
    public HashSet<Guid> Members { get; } = new();

    public override bool HasAccess(Guid userId) => Members.Contains(userId);
}
